#!/usr/bin/env python3
"""FS3 v208 - real sizes, a world per mission, the camera, MediaVP 5.0.2
engine flames, warp and shield hits.

    Sizes      Every hull at its real length (3.75 units a metre; the
               Myrmidon of 16 m stays at 60).
    World      Each mission has a world large enough for its ships and for
               everything that can be called in (the Colossus). The old
               missions are scaled roughly: their places grow by as much as
               their largest ship has grown. Speeds and ranges unchanged.
    Camera     Follows once the player leaves the middle of the picture.
               Z switches the overview (three times further out); in the key
               table as 'overview'.
    Markers    At the edge of the picture as in FreeSpace: two triangles,
               filled ahead, outlined behind, the distance in metres. For
               capital ships and enemy fighters within about 640 m.
    Flames     In 3D from the POF thruster points (FUEL), with the MediaVP
               5.0.2 flames by species; they replace the old flames.
    Warp       The MediaVP 5.0.2 warp model (Warp.pof) with WarpMap01 and
               WarpGlow01 (Knossos: WarpMap02, WarpGlow02).
    Shields    The hit animation by species: ShieldHit01a/02a/03a.
    Settings   DONE on every tab.
    Test area  ?test=5: capital ships of both sides and fighters.
    Missions   Places from the old field are scaled at spawn, and so are the
               scripted crossings (crossLeft, cross), so a mission keeps its
               length.

Needs v207. Edits src/10_core.js, 12_audio.js, 20_render.js, 30_waves.js,
40_world.js, 50_combat.js, 59_field3d.js, 60_effects.js, 70_ui.js and the
tests callsim.js, docksim.js, hudsim.js, mechsim.js, pausesim.js, ramsim.js,
shipsim.js, wpnsim.js, fieldsim.js. Model and effect files in models_v208.zip.
Run assemble.py 208 afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/70_ui.js"):
    sys.exit("Abbruch: erst v207 einspielen.")
if "const BINDS = [" not in open("src/70_ui.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v207 einspielen.")
if "function worldForWave" in open("src/40_world.js", encoding="utf-8").read():
    sys.exit("v208 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
